  "track.runtime.m.counter.ctl.child.stable": "title = \"Counter\" (stable)",
  "track.runtime.m.counter.ctl.child.unstable": "tags = listOf(\"a\") (unstable, new instance)",
  "track.runtime.m.counter.diagramTitle": "Runtime diagram: the +1 flow",
  "track.runtime.m.counter.diagramDesc": "From the UI tree (the button) through Snapshot, Recomposer, Composer, Applier and the phases.",
